class TestSessionLoad:
    """Test that loadSession correctly parses audio + SRT."""

    def test_ref_peaks_populated(self, bridge):
        assert len(bridge.refPeaks) > 0, "refPeaks should be non-empty after load"

    def test_peaks_interleaved_min_max(self, bridge):
        # Peaks are interleaved [min0, max0, min1, max1, ...]
        assert len(bridge.refPeaks) % 2 == 0, "peaks must be even (min/max pairs)"

    def test_audio_duration_positive(self, bridge):
        assert bridge.audioDuration > 0, "audioDuration should be positive"
        # Our test file is 5 seconds
        assert 4.9 < bridge.audioDuration < 5.1

    def test_segment_model_count(self, bridge):
        assert bridge.segmentModel.rowCount() == 2, "SRT has 2 segments"

    def test_segment_model_data(self, bridge):
        from editor_bridge import SegmentModel

        model = bridge.segmentModel
        idx0 = model.index(0)

        # Segment 1: 00:00:00,500 --> 00:00:02,500
        assert model.data(idx0, SegmentModel.StartMsRole) == 500
        assert model.data(idx0, SegmentModel.EndMsRole) == 2500
        assert "segment one" in model.data(idx0, SegmentModel.TextRole)

        idx1 = model.index(1)
        # Segment 2: 00:00:03,000 --> 00:00:04,800
        assert model.data(idx1, SegmentModel.StartMsRole) == 3000
        assert model.data(idx1, SegmentModel.EndMsRole) == 4800

    def test_ref_audio_path(self, bridge):
        assert bridge.refAudioPath == str(REF_WAV)

    def test_srt_text_at_position(self, bridge):
        # Position at 1.0s should be in segment 1 (500-2500ms)
        text = bridge.getSrtTextAt(1.0)
        assert "segment one" in text

        # Position at 3.5s should be in segment 2 (3000-4800ms)
        text = bridge.getSrtTextAt(3.5)
        assert "segment two" in text

        # Position at 2.8s should be between segments (empty)
        text = bridge.getSrtTextAt(2.8)
        assert text == ""


class TestSaveAlignment:
    """Test alignment.json save/load round-trip."""

    def test_save_produces_json(self, bridge, tmp_path):
        out = tmp_path / "alignment.json"
        bridge.saveAlignment(str(out))

        assert out.exists(), "alignment.json should be created"
        data = json.loads(out.read_text())
        assert len(data) == 2, "Should have 2 segments"

    def test_saved_segment_fields(self, bridge, tmp_path):
        out = tmp_path / "alignment.json"
        bridge.saveAlignment(str(out))

        data = json.loads(out.read_text())
        seg = data[0]
        assert "index" in seg
        assert "start_ms" in seg
        assert "end_ms" in seg
        assert "text" in seg
        assert seg["start_ms"] == 500
        assert seg["end_ms"] == 2500

    def test_save_default_path(self, bridge, tmp_path):
        """saveAlignment('') should write to output_dir/alignment.json."""
        # Override output dir to tmp
        bridge._output_dir = tmp_path
        bridge.saveAlignment("")

        out = tmp_path / "alignment.json"
        assert out.exists()


