class TestSegmentAccessors:
    """Test the new segment accessor slots used by QML."""

    def test_get_segment_start_ms(self, bridge):
        assert bridge.getSegmentStartMs(0) == 500
        assert bridge.getSegmentStartMs(1) == 3000
        assert bridge.getSegmentStartMs(99) == -1  # out of bounds

    def test_get_segment_end_ms(self, bridge):
        assert bridge.getSegmentEndMs(0) == 2500
        assert bridge.getSegmentEndMs(1) == 4800

    def test_get_segment_text(self, bridge):
        assert "segment one" in bridge.getSegmentText(0)
        assert "segment two" in bridge.getSegmentText(1)
        assert bridge.getSegmentText(99) == ""

    def test_get_segment_similarity(self, bridge):
        # No recording yet, so similarity is 0
        assert bridge.getSegmentSimilarity(0) == 0.0

    def test_find_segment_at(self, bridge):
        assert bridge.findSegmentAt(1500) == 0
        assert bridge.findSegmentAt(3500) == 1
        assert bridge.findSegmentAt(2800) == -1  # gap between segments
        assert bridge.findSegmentAt(0) == -1  # before first segment


class TestGapConstraint:
    """Test minimum gap constraint on segment boundary updates."""

    def test_overlap_prevented(self, bridge):
        """Moving segment 0 end past segment 1 start is clamped."""
        # Seg 0: 500-2500, Seg 1: 3000-4800
        # Try to set seg 0 end to 3100 — should be clamped to 2900 (3000 - 100)
        bridge.updateSegmentBounds(0, 500, 3100)
        assert bridge.getSegmentEndMs(0) == 2900

    def test_start_after_prev_end_clamped(self, bridge):
        """Moving segment 1 start before segment 0 end is clamped."""
        # Seg 0: 500-2500, Seg 1: 3000-4800
        # Try to set seg 1 start to 2400 — should be clamped to 2600 (2500 + 100)
        bridge.updateSegmentBounds(1, 2400, 4800)
        assert bridge.getSegmentStartMs(1) == 2600

    def test_minimum_segment_length(self, bridge):
        """Segment shorter than 100ms is rejected."""
        # Seg 0: 500-2500 — try to set to 500-550 (50ms)
        bridge.updateSegmentBounds(0, 500, 550)
        # Should be unchanged (500-2500 from fixture)
        assert bridge.getSegmentEndMs(0) == 2500


